 ["StaticMesh /Game/Ratshaker/LA/Props/Photo_Key/RS_SM_Photo_Key_Pieces_Plane_004.RS_SM_Photo_Key_Pieces_Plane_004"]={x=0,y=0,z=12.610867083072662},
